(async function(){
'use strict';
const C=window.PMCore,E=C.escape,$=s=>document.querySelector(s),cfg=window.ANDAMAN_CONFIG||{};
const paths={book:'M12 5v16 M12 5C8 2 4 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-4-1-7-2-10 1',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V5h7l2 2h9v13H3z',wallet:'M3 6h17v14H3z M3 6V3h15v3 M15 11h6v5h-6z',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2z M8 7h8 M8 11h8 M8 15h5','check-circle':'M21 11v1a9 9 0 1 1-5-8 M9 11l3 3L22 4',bolt:'m13 2-9 12h7l-1 8 10-12h-8z',chart:'M4 3v18h18 M8 15l4-5 4 3 5-7',paperclip:'m9 17 9-9a4 4 0 0 0-6-6L3 11a6 6 0 0 0 9 9l9-9 M6 14l9-9',files:'M8 3h12v15H8z M4 7v15h12',network:'M9 2h6v6H9z M2 16h6v6H2z M16 16h6v6h-6z M12 8v4 M5 16v-4h14v4',users:'M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M20 15a4 4 0 0 1 3 4v2',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',history:'M3 11a9 9 0 1 1 2 7 M3 3v8h8 M12 7v5l3 2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',menu:'M3 6h18 M3 12h18 M3 18h18',logout:'M9 4H3v16h6 M12 12h10 M17 7l5 5-5 5','file-plus':'M14 2H4v20h16V8z M14 2v6h6 M8 14h8 M12 10v8',plus:'M12 4v16 M4 12h16',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',arrow:'M4 12h16 M14 6l6 6-6 6',refresh:'M20 7a8 8 0 1 0 1 8 M20 2v5h-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.files}"/></svg>`;
const uiMenus=[...C.menus,['guide','คู่มือการกรอกข้อมูล','book']];
const state={me:null,demo:false,raw:null,data:null,page:'dashboard',fy:C.fy(),query:'',filter:'all',busy:false,reportContext:null,reportsView:'v2',v2Ready:false};
let client=null,db=null,timer,toastTimer,loading=false,authEpoch=0;
try{client=window.supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false,storageKey:'andaman-pm-auth'}});}catch{}
try{db=await new Promise((res,rej)=>{const r=indexedDB.open('andaman-pm-demo-v3',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}catch{}
async function local(method,value){if(!db)return null;return new Promise((res,rej)=>{const tx=db.transaction('state',method==='get'?'readonly':'readwrite'),q=tx.objectStore('state')[method](...(method==='put'?[value,'demo']:['demo']));q.onsuccess=()=>{};tx.oncomplete=()=>res(q.result);tx.onerror=()=>rej(tx.error||q.error);tx.onabort=()=>rej(tx.error||Error('พื้นที่จัดเก็บไม่พร้อม'));});}
function toast(t,error=false){$('#toast').textContent=t;$('#toast').className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',6500);}
function paintIcons(){document.querySelectorAll('[data-icon]').forEach(x=>{x.innerHTML=icon(x.dataset.icon);x.removeAttribute('data-icon');});}
function can(menu,op='read'){if(menu==='guide')return !!state.me?.active&&op==='read';return C.allowed(state.data||{permissions:[]},state.me,menu,op);}
const unit=id=>state.data?.units.find(x=>x.id===id)?.name||id||'—',project=id=>state.data.projects.find(x=>x.id===id),source=id=>state.data.sources.find(x=>x.id===id),badge=s=>`<span class="badge ${E(s)}">${E(C.statuses[s]||s)}</span>`,date=s=>s?new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short',year:'numeric'}).format(new Date(s.length===10?s+'T12:00:00+07:00':s)):'—';
const btn=(text,action,id='',cls='',ico='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${id?`data-id="${E(id)}"`:''}>${ico?icon(ico):''}${text}</button>`;
const years=()=>[...new Set([C.fy(),state.fy,...(state.data?.sources||[]).map(x=>x.fiscal_year),...(state.data?.projects||[]).map(x=>x.fiscal_year)])].sort((a,b)=>b-a);
const options=(rows,value,label,selected='',empty='กรุณาเลือก')=>`<option value="">${empty}</option>`+rows.map(x=>`<option value="${E(x[value])}" ${String(x[value])===String(selected)?'selected':''}>${E(typeof label==='function'?label(x):x[label])}</option>`).join('');
const input=(label,name,value='',type='text',extra='',full=false)=>`<label class="${full?'full':''}">${label}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;
const area=(label,name,value='',required=false)=>`<label class="full">${label}<textarea name="${name}" ${required?'required':''}>${E(value)}</textarea></label>`;
const select=(label,name,content,extra='',full=false)=>`<label class="${full?'full':''}">${label}<select name="${name}" aria-label="${E(label)}" ${extra}>${content}</select></label>`;
const moneyInput=(label,name,value='')=>input(label,name,value,'number','required min="0.01" step="0.01" max="999999999999.99"');
const yearInput=()=>input('ปีงบประมาณ (พ.ศ.)','fiscal_year',state.fy,'number','required min="2500" max="2800"');
const unitSelect=(sel=state.me.unit_id)=>select('หน่วยงานรับผิดชอบ','unit_id',options(state.data.units.filter(x=>x.active&&(state.me.role!=='officer'||x.id===state.me.unit_id)),'id','name',sel),'required',true);
const projectSelect=sel=>select('โครงการ','project_id',options(state.data.projects.filter(x=>x.fiscal_year===state.fy&&!['completed','cancelled'].includes(x.status)),'id',x=>x.code+' · '+x.title,sel),'required',true);
const fundSelect=sel=>select('แหล่งงบประมาณ','source_id',options(state.data.sources.filter(x=>x.fiscal_year===state.fy),'id',x=>x.name+' · ยังไม่จัดสรร '+C.money(C.fundStats(state.data,x.id).unallocated)+' บาท',sel),'required',true);
function modal(title,html,wide=false){const el=$('#modal');$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;el.classList.toggle('wide',wide);if(!el.open)el.showModal();paintIcons();}
function form(kind,content,submit='บันทึก',ctx={}){state.modalContext={kind,command_id:C.uuid(),...ctx};return `<form id="action-form" data-kind="${kind}"><div class="form-grid">${content}</div><p class="form-error" role="alert" style="color:#ba6175;font-size:12px;margin-top:14px"></p><div class="form-buttons">${btn('ยกเลิก','close-modal')}<button class="btn primary" type="submit">${submit}</button></div></form>`;}
function header(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="buttons">${actions}</div></div>`;}
function empty(title='ยังไม่มีรายการ',detail='รายการที่บันทึกจะแสดงที่นี่',action=''){return `<div class="empty">${icon('folder')}<h3>${title}</h3><p>${detail}</p>${action}</div>`;}
function table(heads,rows){return `<div class="card table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}">${empty()}</td></tr>`}</tbody></table></div>`;}
function pills(values){return `<div class="toolbar"><div class="pills">${[['all','ทั้งหมด'],...values].map(([k,t])=>`<button class="pill ${state.filter===k?'active':''}" data-action="filter" data-id="${k}">${t}</button>`).join('')}</div><p>ข้อมูลปีงบประมาณ ${state.fy}</p></div>`;}
function rows(key){const q=state.query.toLocaleLowerCase();return state.data[key].filter(x=>(x.fiscal_year===undefined||+x.fiscal_year===state.fy)&&(state.filter==='all'||x.status===state.filter)&&(!q||[x.title,x.purpose,x.name,x.code,unit(x.unit_id),x.display_name,x.email,x.action].join(' ').toLocaleLowerCase().includes(q)));}
function kpi(title,value,sub,ico='wallet'){return `<div class="kpi"><div class="kpi-title">${title}<span class="kpi-icon">${icon(ico)}</span></div><div class="kpi-value">${value}</div><p class="kpi-sub">${sub}</p></div>`;}
function login(message=''){state.me=null;$('#app-root').hidden=true;$('#login-root').hidden=false;$('#login-root').innerHTML=`<div class="login-page"><section class="login-story"><div class="login-brand"><img src="logo.jpg" alt="ตราสถาบัน"><div><b>ANDAMAN PM</b><small>PROJECT & BUDGET</small></div></div><div class="eyebrow">SOUTHERN VOCATIONAL INSTITUTE 2</div><h1>บริหารโครงการอย่างเป็นระบบ<br><strong>เชื่อมทุกงบประมาณ<br>สู่ผลลัพธ์ของสถาบัน</strong></h1><p>ระบบบริหารจัดการโครงการและงบประมาณ<br>สถาบันการอาชีวศึกษาภาคใต้ 2</p><div class="login-features"><div><strong>12</strong>หน่วยงานและสถานศึกษา</div><div><strong>3</strong>ระดับสิทธิ์การใช้งาน</div><div><strong>ครบวงจร</strong>เสนอ · อนุมัติ · ติดตาม</div></div></section><section class="login-card"><div class="login-icon">${icon('shield')}</div><h2>เข้าสู่ระบบ</h2><p>เข้าใช้งานด้วยบัญชีที่ผู้ดูแลระบบจัดให้</p><form id="login-form"><label>อีเมล / ชื่อผู้ใช้<input name="email" autocomplete="username" placeholder="อีเมล หรือ admin" required></label><label>รหัสผ่าน<input name="password" type="password" autocomplete="current-password" placeholder="รหัสผ่านของคุณ" required></label><div class="login-error" role="alert">${E(message)}</div><button type="submit" class="btn primary">เข้าสู่ระบบ ${icon('arrow')}</button></form><div class="login-divider">สำรวจการทำงานของระบบ</div><button class="btn demo-button" data-action="demo-picker">${icon('eye')} ทดลองใช้งานด้วยข้อมูลตัวอย่าง</button><div class="login-note">สิทธิ์เข้าถึงข้อมูลกำหนดตามบทบาทและหน่วยงาน<br>ใช้ได้ทั้งคอมพิวเตอร์ แท็บเล็ต และโทรศัพท์</div></section></div>`;}
async function fetchAll(name){if(name==='audit'){const {data,error}=await client.from('pm_audit').select('*').order('created_at',{ascending:false}).limit(1000);if(error)throw error;return data;}let out=[];for(let i=0;i<11;i++){const {data,error}=await client.from('pm_'+name).select('*').order(name==='members'?'user_id':name==='permissions'?'role':'id').range(i*1000,i*1000+999);if(error)throw error;if(!data.length)return out;out.push(...data);if(data.length<1000)return out;}throw Error('รายการมีจำนวนมาก กรุณาติดต่อผู้ดูแลเพื่อเพิ่มการแบ่งหน้า');}
async function refresh(renderPage=true){if(loading)return;loading=true;try{if(state.demo){state.me=state.raw.members.find(x=>x.role===state.me.role&&x.active)||state.raw.members.find(x=>x.active);state.data=C.scopedDemo(state.raw,state.me);}else{const {data:u,error:ue}=await client.auth.getUser();if(ue||!u.user)throw Error('กรุณาเข้าสู่ระบบใหม่');const {data:m,error:me}=await client.from('pm_members').select('*').eq('user_id',u.user.id).maybeSingle();if(me)throw me;if(!m?.active){await client.auth.signOut();throw Error('บัญชีนี้ยังไม่ได้รับสิทธิ์ในระบบโครงการ กรุณาติดต่อ Admin');}state.me=m;const keys=['units','members','permissions','sources','proposals','projects','allocations','disbursements','reports','forms','documents','audit'];const all=await Promise.all(keys.map(fetchAll));const d=Object.fromEntries(keys.map((k,i)=>[k,all[i]]));const {data:b,error}=await client.rpc('pm_fund_balances');if(error)throw error;d.fund_balances=b||[];state.data=d;}
if(renderPage)shell();$('#sync-status').textContent='ปรับปรุง '+new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'});}
finally{loading=false;}}
async function enterDemo(role){state.raw=await local('get');if(state.raw?.version!==3)state.raw=C.demoData();state.demo=true;state.me=state.raw.members.find(x=>x.role===role&&x.active)||state.raw.members[0];await local('put',state.raw);$('#modal').close();state.page='dashboard';await refresh();}
async function mutate(action,data,command=state.modalContext?.command_id||C.uuid()){if(state.busy)throw Error('กำลังบันทึก กรุณารอสักครู่');state.busy=true;try{let response;if(state.demo){const result=C.demoAction(state.raw,state.me,action,{...data,command_id:command});state.raw=result.data;await local('put',state.raw);response=result.response;}else{const {data:r,error}=await client.rpc('pm_action',{p_action:action,p_data:{...data,command_id:command}});if(error)throw error;response=r;}await refresh(false);return response;}finally{state.busy=false;}}
async function navigate(page){if(!can(page))return toast('ไม่มีสิทธิ์เข้าถึงเมนูนี้',true);if(page!=='reports'){try{await flushReportWorkspace();}catch(err){toast(err.message,true);return;}}state.page=page;state.filter='all';state.reportContext=null;location.hash=page;$('#sidebar').classList.remove('open');shell();window.scrollTo(0,0);}
function shell(){if(!state.me)return;$('#login-root').hidden=true;$('#app-root').hidden=false;$('#demo-banner').hidden=!state.demo;$('#demo-role').value=state.me.role;$('#side-name').textContent=state.me.display_name;$('#side-role').textContent=C.roleNames[state.me.role];$('#side-avatar').textContent=state.me.display_name.slice(0,1);$('#role-pill').textContent=C.roleNames[state.me.role];if(!can(state.page))state.page=uiMenus.find(([k])=>can(k))?.[0]||'dashboard';$('#main-nav').innerHTML=uiMenus.filter(([k])=>can(k)).map(([k,t,i],n)=>`${['sources','reports','members','guide'].includes(k)?'<div class="nav-separator"></div>':''}<a href="#${k}" data-page="${k}" class="nav-item ${state.page===k?'active':''}">${icon(i)}<span>${t}</span>${k==='proposals'&&state.data.proposals.some(x=>x.status==='pending')?'<i class="nav-dot"></i>':''}</a>`).join('');$('#current-page').textContent=uiMenus.find(x=>x[0]===state.page)?.[1]||'ภาพรวม';$('#fiscal-filter').innerHTML=years().map(y=>`<option value="${y}" ${y===state.fy?'selected':''}>ปีงบฯ ${y}</option>`).join('');const alerts=C.pending(state.data,state.me,state.fy);$('#notification-count').textContent=alerts.length;$('#notification-count').hidden=!alerts.length;render();paintIcons();}
function monthlyChart(paid){let vals=Array(12).fill(0);paid.forEach(w=>{const s=w.payment_date;if(s){const [y,m]=s.split('-').map(Number),idx=(m+2)%12;if((m>=10?y+544:y+543)===state.fy)vals[idx]+=+w.amount;}});let total=0;vals=vals.map(x=>total+=x);const max=Math.max(...vals,1000),ys=[0,1,2,3,4].map(i=>{const y=180-i*39;return `<line class="gridline" x1="50" x2="620" y1="${y}" y2="${y}"/><text x="40" y="${y+3}" text-anchor="end">${max*i/4>=1000000?(max*i/4/1000000).toFixed(1)+'M':Math.round(max*i/4000)+'k'}</text>`;}).join('');const pts=vals.map((v,i)=>[54+i*51,180-v/max*156]),path=pts.map(([x,y],i)=>(i?'L':'M')+x+','+y).join(' ');return `<svg class="line-chart" viewBox="0 0 640 220" role="img" aria-label="กราฟยอดจ่ายจริงสะสมรายเดือนปีงบประมาณ ${state.fy}"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#6093ed" stop-opacity=".18"/><stop offset="1" stop-color="#6093ed" stop-opacity="0"/></linearGradient></defs>${ys}<path d="${path} L615,180 L54,180Z" fill="url(#area)"/><path d="${path}" stroke="#5489e9" stroke-width="2.5" fill="none"/>${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="2.5" fill="#fff" stroke="#5489e9" stroke-width="1.5"/>`).join('')}${['ต.ค.','พ.ย.','ธ.ค.','ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.'].map((m,i)=>`<text x="${54+i*51}" y="207" text-anchor="middle">${m}</text>`).join('')}</svg>`;}
function dashboard(){const d=state.data,ps=rows('projects'),funds=rows('sources'),ws=rows('disbursements').filter(x=>state.me.role!=='officer'||!!x.project_id),officer=state.me.role==='officer',budget=officer?C.sum(d.allocations.filter(a=>ps.some(p=>p.id===a.project_id))):C.sum(funds),paid=C.sum(ws.filter(x=>x.status==='paid')),reserved=C.sum(ws.filter(x=>['pending','approved'].includes(x.status))),available=Math.max(0,budget-paid-reserved),pct=budget?Math.min(100,paid/budget*100):0,alerts=C.pending(d,state.me,state.fy),counts=ps.filter(x=>x.status==='completed').length;const colors=['#558ae9','#f0bd6a','#dce8fc'];let offset=0;const arcs=[paid,reserved,available].map((v,i)=>{const part=budget?v/budget*414.69:0,r=`<circle cx="80" cy="80" r="66" fill="none" stroke="${colors[i]}" stroke-width="17" stroke-dasharray="${part} ${414.69-part}" stroke-dashoffset="${-offset}"/>`;offset+=part;return r;}).join('');return header('ภาพรวมโครงการและงบประมาณ','ติดตามงบประมาณ การดำเนินงาน และรายการที่รอพิจารณา',btn('ส่งออกสรุป','export-csv','','','download'))+`<section class="welcome"><div><span class="eyebrow">INSTITUTION OVERVIEW / ${state.fy}</span><h2>ทุกโครงการ เชื่อมสู่เป้าหมายเดียวกัน</h2><p>${officer?E(unit(state.me.unit_id)):'สถาบันการอาชีวศึกษาภาคใต้ 2 · ภาพรวมทุกหน่วยงาน'}</p>${can('proposals','write')?btn('สร้างข้อเสนอโครงการ','proposal-new','','','plus'):btn('ติดตามโครงการ','go-projects','','','arrow')}</div><div class="hero-summary"><div class="hero-ring" style="--pct:${pct}%"><div>${pct.toFixed(1)}<small style="font-size:12px">%</small></div></div><div><b>การเบิกจ่ายงบประมาณ</b><p>จ่ายจริงเทียบวงเงิน${officer?'จัดสรร':'ทั้งหมด'}</p></div></div></section><div class="kpis">${kpi(officer?'งบจัดสรรของหน่วยงาน':'งบประมาณทั้งหมด',C.money(budget),`${funds.length} แหล่งเงิน · ปีงบประมาณ ${state.fy}`)}${kpi('โครงการทั้งหมด',ps.length+'<small>โครงการ</small>',`เสร็จสิ้น ${counts} · ดำเนินงาน ${ps.length-counts}`,'folder')}${kpi('รออนุมัติ / อนุมัติรอจ่าย',C.money(reserved),'กันวงเงินแล้วตั้งแต่ส่งคำขอ','receipt')}${kpi('เบิกจ่ายจริงแล้ว',C.money(paid),'คงเหลือหลังจ่าย '+C.money(budget-paid)+' บาท','check-circle')}</div><div class="dashboard-grid"><section class="card"><div class="card-header"><div><h2>แนวโน้มการเบิกจ่ายงบประมาณ</h2><p>ยอดจ่ายจริงสะสมตามเดือนในปีงบประมาณ</p></div><div class="legend"><span><i style="background:#568ae9"></i>จ่ายจริงสะสม</span></div></div><div class="card-body">${monthlyChart(ws.filter(x=>x.status==='paid'))}</div></section><section class="card"><div class="card-header"><div><h2>สัดส่วนการใช้จ่ายงบประมาณ</h2><p>${officer?'เฉพาะหน่วยงานที่มีสิทธิ์เข้าถึง':'รวมโครงการและงบส่วนกลาง'}</p></div>${icon('chart')}</div><div class="card-body"><div class="donut-wrap"><div class="donut"><svg viewBox="0 0 160 160"><circle cx="80" cy="80" r="66" fill="none" stroke="#eef3fb" stroke-width="17"/>${arcs}</svg><div class="donut-center"><strong>${pct.toFixed(1)}<small>%</small></strong><small>เบิกจ่ายแล้ว</small></div></div><div class="donut-legend">${[['จ่ายแล้ว',paid],['รออนุมัติ / รอจ่าย',reserved],['ยังไม่ผูกพัน',available]].map(([t,v],i)=>`<div><i style="background:${colors[i]}"></i><span>${t}<b>${C.money(v)} บาท</b></span></div>`).join('')}</div></div></div></section></div><div class="dashboard-grid"><section class="card"><div class="card-header"><div><h2>งบจัดสรรตามหน่วยงาน</h2><p>เปรียบเทียบวงเงินจัดสรรในแต่ละหน่วยงาน</p></div>${btn('ดูโครงการ','go-projects','','text small')}</div><div class="card-body">${d.units.map(u=>{const val=C.sum(d.allocations.filter(a=>ps.some(p=>p.id===a.project_id&&p.unit_id===u.id)));return {...u,val};}).filter(u=>u.val).sort((a,b)=>b.val-a.val).slice(0,6).map(u=>`<div class="unit-row"><span class="unit-name">${E(u.name)}</span><div class="unit-bar"><span style="width:${budget?u.val/budget*100:0}%"></span></div><strong>${C.money(u.val)}</strong></div>`).join('')||empty('ยังไม่มีการจัดสรรงบ','เริ่มจากเพิ่มแหล่งเงินและอนุมัติข้อเสนอโครงการ')}</div></section><section class="card"><div class="card-header"><div><h2>รายการที่ต้องติดตาม</h2><p>${alerts.length} รายการรอดำเนินการ / เลยกำหนด</p></div>${icon('bell')}</div><div class="card-body">${alerts.slice(0,4).map(x=>`<div class="pending-row"><div class="pending-icon">${icon(x.menu==='reports'?'chart':'receipt')}</div><div><h3>${E(x.title)}</h3><p>${E(x.detail)}</p></div>${btn('เปิด','notification-go',x.menu,'small text')}</div>`).join('')||empty('ไม่มีรายการค้าง','รายการใหม่จะแจ้งเตือนที่มุมขวาบน')}</div></section></div>`+projectTable(ps.slice(0,5),true);}
function projectTable(ps,short=false){return `${short?'<h2 class="section-title">โครงการล่าสุด</h2>':''}`+table(['โครงการ / ผู้รับผิดชอบ','หน่วยงาน','วงเงินจัดสรร','จ่ายแล้ว','ความก้าวหน้า','สถานะ','จัดการ'],ps.map(p=>{const s=C.projectStats(state.data,p.id);return `<tr><td class="title-cell"><strong>${E(p.title)}</strong><small>${E(p.code)} · ${E(p.owner_name)}</small></td><td>${E(unit(p.unit_id))}</td><td class="money">${C.money(s.allocated)}</td><td class="money positive">${C.money(s.paid)}</td><td><div class="progress-label"><div class="progress"><i style="width:${p.progress}%"></i></div><span>${p.progress}%</span></div></td><td>${badge(p.status)}</td><td><div class="table-actions">${btn('รายละเอียด','project-detail',p.id,'small')}${can('projects','write')&&!['completed','cancelled'].includes(p.status)?btn('อัปเดต','progress',p.id,'small'):''}</div></td></tr>`;}));}
function proposals(){return header('เสนอโครงการ','จัดทำข้อเสนอ → พิจารณาอนุมัติ → สร้างโครงการให้อัตโนมัติ',can('proposals','write')?btn('เสนอโครงการใหม่','proposal-new','','primary','plus'):'')+pills([['draft','ฉบับร่าง'],['pending','รอพิจารณา'],['approved','อนุมัติแล้ว'],['returned','ส่งกลับแก้ไข']])+table(['ชื่อข้อเสนอ','หน่วยงาน','งบประมาณที่ขอ','สถานะ','จัดการ'],rows('proposals').map(p=>`<tr><td class="title-cell"><strong>${E(p.title)}</strong><small>${E(p.owner_name)} · ${date(p.created_at)}</small></td><td>${E(unit(p.unit_id))}</td><td class="money">${C.money(p.requested_budget)}</td><td>${badge(p.status)}</td><td><div class="table-actions">${btn('ดู / พิจารณา','proposal-detail',p.id,'small')}${can('proposals','write')&&['draft','returned'].includes(p.status)&&(p.owner_id===state.me.user_id||state.me.role==='admin')?btn('แก้ไข','proposal-edit',p.id,'small'):''}</div></td></tr>`));}
function sources(){return header('แหล่งงบประมาณ','แยกวงเงินจัดสรรโครงการ งบส่วนกลาง และงบที่ยังไม่ผูกพัน',can('sources','write')?btn('เพิ่มแหล่งงบประมาณ','source-new','','primary','plus'):'')+`<div class="info">วงเงินที่ยังไม่จัดสรร = งบตั้งต้น − ยอดจัดสรรให้โครงการ − คำขอส่วนกลางที่รออนุมัติ / อนุมัติ / จ่ายแล้ว</div>`+table(['แหล่งงบประมาณ','วงเงินทั้งหมด','จัดสรรโครงการ','ผูกพันส่วนกลาง','ยังไม่จัดสรร','จัดการ'],rows('sources').map(s=>{const v=C.fundStats(state.data,s.id);return `<tr><td class="title-cell"><strong>${E(s.name)}</strong><small>${E(s.note)}</small></td><td class="money">${C.money(s.amount)}</td><td class="money">${C.money(v.allocated)}</td><td class="money">${C.money(v.central_reserved)}</td><td class="money positive">${C.money(v.unallocated)}</td><td>${can('sources','write')?btn('ปรับวงเงิน','source-adjust',s.id,'small'):'—'}</td></tr>`;}));}
function allocations(){const a=state.data.allocations.filter(x=>project(x.project_id)?.fiscal_year===state.fy&&(!state.query||project(x.project_id)?.title.includes(state.query)));return header('จัดสรรงบโครงการ','จัดสรรจากแหล่งเงินให้โครงการภายในวงเงินที่ได้รับอนุมัติ',can('allocations','write')?btn('บันทึกการจัดสรร','allocation-new','','primary','plus'):'')+table(['โครงการ','แหล่งเงิน','จำนวนเงิน','วันที่จัดสรร','หมายเหตุ'],a.map(x=>`<tr><td class="title-cell"><strong>${E(project(x.project_id)?.title)}</strong><small>${E(project(x.project_id)?.code)}</small></td><td>${E(source(x.source_id)?.name)}</td><td class="money">${C.money(x.amount)}</td><td>${date(x.created_at)}</td><td>${E(x.note)}</td></tr>`));}
function claims(mode='disbursements'){const pay=mode==='payments',utility=mode==='utilities';let list=rows('disbursements');if(pay)list=list.filter(x=>['approved','paid'].includes(x.status));if(utility)list=list.filter(x=>x.source_id);const title=pay?'บันทึกจ่ายจริง':utility?'งบส่วนกลาง / สาธารณูปโภค':'คำขอเบิกจ่าย';return header(title,pay?'บันทึกเลขที่หลักฐานและวันที่จ่ายสำหรับรายการที่อนุมัติแล้ว':'คำขอรอพิจารณาจะกันวงเงินไว้ทันที เพื่อตรวจสอบยอดใช้ได้จริง',!pay&&can(mode,'write')?btn(utility?'เพิ่มคำขอส่วนกลาง':'สร้างคำขอเบิกจ่าย',utility?'utility-new':'claim-new','','primary','plus'):'')+pills(pay?[['approved','อนุมัติรอจ่าย'],['paid','จ่ายแล้ว']]:[['pending','รอพิจารณา'],['approved','อนุมัติแล้ว'],['paid','จ่ายแล้ว'],['rejected','ไม่อนุมัติ']])+table(['รายการขอเบิกจ่าย','โครงการ / หน่วยงาน','จำนวนเงิน','สถานะ','จัดการ'],list.map(w=>`<tr><td class="title-cell"><strong>${E(w.purpose)}</strong><small>${E(w.requester_name)} · ${date(w.created_at)}</small>${w.voucher_no?`<small>หลักฐาน ${E(w.voucher_no)} · ${date(w.payment_date)}</small>`:''}</td><td>${E(w.project_id?project(w.project_id)?.title:source(w.source_id)?.name)}<small>${E(unit(w.unit_id))}</small></td><td class="money">${C.money(w.amount)}</td><td>${badge(w.status)}</td><td>${btn(pay&&w.status==='approved'&&can('payments','write')?'บันทึกจ่าย':'รายละเอียด','claim-detail',w.id,'small')}</td></tr>`));}
function reportTracking(){const list=rows('projects');return `<div class="reports-tracking-head"><div><h2>ติดตามรายงานโครงการ</h2><p>กำหนดส่ง สถานะตรวจรับ และยอดงบประมาณจากข้อมูลโครงการ</p></div>${btn('ส่งออกสถานะ','export-csv','','','download')}</div><div class="info">เลือก “จัดทำรายงาน” เพื่อใช้ Andaman Report พร้อมข้อมูลชื่อโครงการ หน่วยงาน งบจัดสรร และยอดจ่ายจริงอัตโนมัติ</div>`+table(['โครงการ','กำหนดส่งรายงาน','งบจัดสรร / จ่ายจริง','สถานะรายงาน','จัดการ'],list.map(p=>{const r=state.data.reports.find(x=>x.project_id===p.id),s=C.projectStats(state.data,p.id);return `<tr><td class="title-cell"><strong>${E(p.title)}</strong><small>${E(unit(p.unit_id))} · ${p.progress}%</small></td><td>${date(p.report_due)}${p.report_due&&p.report_due<C.today()&&r?.status!=='accepted'?'<small style="color:#cc7b8c">เลยกำหนดส่ง</small>':''}</td><td class="money">${C.money(s.allocated)}<small>จ่ายจริง ${C.money(s.paid)}</small></td><td>${badge(r?.status||'draft')}${r?.review_note?`<small>${E(r.review_note)}</small>`:''}</td><td><div class="table-actions">${btn(r&&['submitted','accepted'].includes(r.status)?'เปิดรายงาน':'จัดทำรายงาน','report-open',p.id,'small')}${can('reports','approve')&&r?.status==='submitted'&&r.owner_id!==state.me.user_id?btn('ตรวจรับ','report-review',r.id,'small green'):''}</div></td></tr>`;}));}
function reportTabs(){return `<div class="reports-tabs" role="tablist" aria-label="มุมมองรายงาน">${[['v2','Andaman Report v2.0','files'],['tracking','ติดตามรายงานโครงการ','chart']].map(([id,label,i])=>`<button type="button" role="tab" id="reports-tab-${id}" aria-controls="reports-panel-${id}" aria-selected="${state.reportsView===id}" tabindex="${state.reportsView===id?0:-1}" data-action="reports-view" data-id="${id}">${icon(i)}${label}</button>`).join('')}</div>`;}
function reports(){state.v2Ready=false;return header('รายงานและการติดตาม','จัดทำรายงานด้วย Andaman Report v2.0 และติดตามรายงานผลของแต่ละโครงการ')+`<section id="reports-workspace">${reportTabs()}<div id="reports-panel-v2" role="tabpanel" aria-labelledby="reports-tab-v2" ${state.reportsView!=='v2'?'hidden':''}><div class="reports-workspace-note">${icon('files')}<p><b>Andaman Report v2.0</b> · สร้างรายงาน เปิดร่างเดิม คำนวณผลประเมิน แนบภาพ และพิมพ์ PDF<br><small>รายงานในส่วนนี้บันทึกในอุปกรณ์นี้ สำรองหรือย้ายเครื่องด้วย JSON ได้ หากต้องการผูกกับโครงการให้เลือกแท็บ “ติดตามรายงานโครงการ”</small></p></div><iframe id="andaman-report-v2-frame" class="report-iframe report-v2-iframe" title="Andaman Report v2.0" src="report-editor/index.html?workspace=1${state.demo?'&demo=1':''}"></iframe></div><div id="reports-panel-tracking" role="tabpanel" aria-labelledby="reports-tab-tracking" ${state.reportsView!=='tracking'?'hidden':''}>${reportTracking()}</div></section>`;}
function updateReportWorkspace(){for(const name of ['v2','tracking']){const selected=state.reportsView===name;$('#reports-tab-'+name).setAttribute('aria-selected',String(selected));$('#reports-tab-'+name).tabIndex=selected?0:-1;$('#reports-panel-'+name).hidden=!selected;}$('#reports-panel-tracking').innerHTML=reportTracking();}
async function flushReportWorkspace(){const frame=$('#andaman-report-v2-frame');if(!frame?.contentWindow||!state.v2Ready)return;const id=C.uuid();return new Promise((resolve,reject)=>{const done=e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow||e.data?.type!=='pm-report-workspace-flushed'||e.data.id!==id)return;cleanup();e.data.error?reject(Error(e.data.error)):resolve();};const cleanup=()=>{clearTimeout(timeout);window.removeEventListener('message',done);};const timeout=setTimeout(()=>{cleanup();reject(Error('ยังบันทึกร่างรายงานไม่เสร็จ กรุณาลองอีกครั้ง'));},4000);window.addEventListener('message',done);frame.contentWindow.postMessage({type:'pm-report-workspace-flush',id},location.origin);});}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('#andaman-report-v2-frame')?.contentWindow&&e.data?.type==='pm-report-workspace-ready')state.v2Ready=true;});

function forms(){return header('คลังแบบฟอร์ม','ดาวน์โหลดแบบฟอร์มมาตรฐานสำหรับขออนุญาต ดำเนินกิจกรรม และเบิกจ่าย',can('forms','write')?btn('เพิ่มแบบฟอร์ม','form-upload','','primary','plus'):'')+`<div class="file-grid">${rows('forms').filter(x=>x.active).map(f=>`<section class="file-card"><div class="file-symbol">${icon('files')}</div><h3>${E(f.title)}</h3><p>${E(f.description||'แบบฟอร์มมาตรฐานของหน่วยงาน')}</p><small>${E(f.file_name)} · ${(f.size_bytes/1024).toFixed(0)} KB</small><div class="buttons">${btn('ดาวน์โหลด','file-download','form:'+f.id,'small','download')}${can('forms','write')?btn('เก็บเข้าคลัง','form-archive',f.id,'small'):''}</div></section>`).join('')}</div>`+(!rows('forms').filter(x=>x.active).length?`<div class="card">${empty('ยังไม่มีแบบฟอร์ม','Admin สามารถเพิ่มไฟล์ PDF, Word, Excel หรือภาพ ให้สมาชิกดาวน์โหลดได้')}</div>`:'');}
function documents(){return header('ไฟล์ขออนุญาต','จัดเก็บคำขออนุญาต หลักฐานดำเนินงาน และเอกสารประกอบรายโครงการ',can('documents','write')?btn('แนบไฟล์โครงการ','document-upload','','primary','plus'):'')+pills([['pending','รอตรวจ'],['accepted','ตรวจรับแล้ว'],['returned','ส่งกลับแก้ไข']])+table(['เอกสาร','โครงการ','ไฟล์','สถานะ','จัดการ'],rows('documents').filter(x=>project(x.project_id)?.fiscal_year===state.fy).map(f=>`<tr><td class="title-cell"><strong>${E(f.title)}</strong><small>${date(f.created_at)}</small></td><td>${E(project(f.project_id)?.title)}</td><td>${E(f.file_name)}<small>${(f.size_bytes/1024).toFixed(0)} KB</small></td><td>${badge(f.status)}<small>${E(f.review_note||'')}</small></td><td><div class="table-actions">${btn('เปิดไฟล์','file-download','doc:'+f.id,'small')}${can('documents','approve')&&f.status==='pending'&&f.owner_id!==state.me.user_id?btn('ตรวจเอกสาร','document-review',f.id,'small green'):''}${can('documents','write')&&f.status==='returned'?btn('แนบฉบับแก้ไข','document-replace',f.id,'small'):''}</div></td></tr>`));}
function units(){const d=state.data,kind={office:'สำนักงาน / หน่วยงาน',bureau:'สำนัก',center:'ศูนย์',college:'สถานศึกษาในสังกัด',work:'กลุ่มงาน'};const line=(u,depth=0)=>`<div class="unit-tree-row ${depth?'child':''}" style="padding-left:${20+depth*26}px"><span class="unit-tree-icon">${icon(u.kind==='college'?'folder':'network')}</span><div><h3>${E(u.name)}</h3><p>${E(kind[u.kind]||u.kind)} · ${d.members.filter(m=>m.unit_id===u.id&&m.active).length} สมาชิกที่มองเห็น</p></div>${can('units','write')?btn('แก้ไข','unit-edit',u.id,'small'):''}</div>`+d.units.filter(x=>x.parent_id===u.id).map(x=>line(x,depth+1)).join('');return header('โครงสร้างหน่วยงาน','5 ส่วนงานสถาบัน และ 7 สถานศึกษาในสังกัด',state.me.role==='admin'?btn('เพิ่มกลุ่มงาน','unit-new','','primary','plus'):'')+`<div class="info">อ้างอิงข้อบังคับการจัดตั้งและแบ่งหน่วยงาน พ.ศ. 2568 · กลุ่มงานย่อยสามารถเพิ่มตามคำสั่งมอบหมายของสถาบัน</div><section class="card">${d.units.filter(x=>!x.parent_id).map(x=>line(x)).join('')}</section>`;}
function members(){return header('จัดการสมาชิก','กำหนดบทบาท หน่วยงาน และสถานะบัญชีสำหรับระบบโครงการ',btn('เพิ่มสมาชิก','member-new','','primary','plus'))+table(['สมาชิก','อีเมล','บทบาท','หน่วยงาน','สถานะ','จัดการ'],rows('members').map(m=>`<tr><td class="title-cell"><strong>${E(m.display_name)}</strong></td><td>${E(m.email)}</td><td><span class="badge">${C.roleNames[m.role]}</span></td><td>${E(unit(m.unit_id))}</td><td><span class="badge ${m.active?'accepted':'rejected'}">${m.active?'ใช้งาน':'ระงับ'}</span></td><td>${btn('จัดการสิทธิ์','member-edit',m.user_id,'small')}</td></tr>`));}
function permissions(){const role=state.permissionRole||'executive';return header('สิทธิ์เมนูตามบทบาท','กำหนดสิทธิ์อ่าน บันทึก และอนุมัติ โดยตรวจสอบซ้ำที่ฐานข้อมูล')+`<div class="toolbar"><label class="form-label">บทบาท<select id="permission-role"><option value="executive" ${role==='executive'?'selected':''}>ผู้บริหาร</option><option value="officer" ${role==='officer'?'selected':''}>เจ้าหน้าที่</option></select></label><p>Admin มีสิทธิ์ทุกเมนู · เจ้าหน้าที่ไม่มีสิทธิ์อนุมัติ</p></div><form id="permissions-form"><div class="card table-scroll"><table class="permission-table"><thead><tr><th>เมนู</th><th>อ่าน / เข้าดู</th><th>บันทึก / แก้ไข</th><th>อนุมัติ / ตรวจรับ</th></tr></thead><tbody>${C.menus.map(([k,t])=>{const p=state.data.permissions.find(x=>x.role===role&&x.menu===k)||{};return `<tr><td>${t}</td>${['read','write','approve'].map(op=>`<td><input type="checkbox" name="${k}:${op}" aria-label="${t} ${op}" ${p['can_'+op]?'checked':''} ${['members','permissions'].includes(k)||op==='approve'&&(role==='officer'||!['proposals','disbursements','reports','documents'].includes(k))?'disabled':''}></td>`).join('')}</tr>`;}).join('')}</tbody></table></div><div class="form-buttons"><button class="btn primary" type="submit">บันทึกสิทธิ์เมนู</button></div></form>`;}
function audit(){return header('ประวัติการดำเนินการ','แสดง 1,000 รายการล่าสุด · ผู้ดำเนินการ เวลา และเหตุผล',btn('ส่งออก CSV','export-csv','','','download'))+table(['วันเวลา','ผู้ดำเนินการ','รายการ','รายละเอียด'],rows('audit').sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(a=>`<tr><td>${date(a.created_at)}<small>${new Date(a.created_at).toLocaleTimeString('th-TH')}</small></td><td>${E(a.actor_name)}</td><td><span class="badge">${E(actionLabel(a.action))}</span><small>${E(a.entity_id||'')}</small></td><td>${E(a.detail?.note||'')}${a.detail?.amount?`<small>${C.money(a.detail.amount)} บาท</small>`:''}${a.detail?.decision?`<small>${E(C.statuses[a.detail.decision]||a.detail.decision)}</small>`:''}</td></tr>`));}
function actionLabel(a){const m=C.menus.find(x=>x[0]===a.split('.')[0])?.[1]||a.split('.')[0],v={create:'เพิ่ม',save:'บันทึก',submit:'ส่ง',review:'พิจารณา',pay:'บันทึกจ่าย',progress:'อัปเดต',adjust:'ปรับวงเงิน',update:'แก้ไข',archive:'เก็บเข้าคลัง',add_existing:'เพิ่มบัญชีเดิม'};return (v[a.split('.')[1]]||'')+' '+m;}
function render(){if(state.page==='reports'&&can('reports')&&$('#reports-workspace')){updateReportWorkspace();return;}const views={dashboard,proposals,sources,allocations,disbursements:()=>claims(),payments:()=>claims('payments'),utilities:()=>claims('utilities'),projects:()=>header('โครงการ / กิจกรรม','ติดตามวงเงิน ความก้าวหน้า และผลดำเนินงานของแต่ละโครงการ',btn('ส่งออกสรุป','export-csv','','','download'))+pills([['planned','รอจัดสรร'],['active','กำลังดำเนินการ'],['completed','เสร็จสิ้น']])+projectTable(rows('projects')),reports,guide:()=>header('คู่มือการกรอกข้อมูล','เปิดหัวข้อที่ต้องการ หรือค้นหาชื่อเมนูและช่องกรอกข้อมูล')+PMUserGuide.renderSystem(),forms,documents,units,members,permissions,audit};if(!can(state.page)){$('#main').innerHTML=empty('ไม่มีเมนูที่ได้รับสิทธิ์','กรุณาติดต่อ Admin เพื่อกำหนดสิทธิ์การใช้งาน');return;}$('#main').innerHTML=(views[state.page]||dashboard)();}
function proposalForm(p={}){modal(p.id?'แก้ไขข้อเสนอโครงการ':'เสนอโครงการใหม่',form('proposal',input('ชื่อโครงการ','title',p.title,'text','required minlength="3"',true)+unitSelect(p.unit_id)+input('ปีงบประมาณ (พ.ศ.)','fiscal_year',p.fiscal_year||state.fy,'number','required min="2500" max="2800"')+moneyInput('งบประมาณที่ขอ (บาท)','requested_budget',p.requested_budget)+input('วันที่เริ่ม','start_date',p.start_date,'date')+input('วันที่สิ้นสุด','end_date',p.end_date,'date')+input('กำหนดส่งรายงาน','report_due',p.report_due,'date')+area('วัตถุประสงค์ (แยกบรรทัด)','objectives',p.objectives,true)+area('รายละเอียด / ความสอดคล้องกับยุทธศาสตร์','description',p.description)+select('การส่งข้อเสนอ','submit_mode','<option value="draft">บันทึกฉบับร่าง</option><option value="submit">ส่งพิจารณา</option>'),'บันทึกข้อเสนอ',{id:p.id,version:p.version}));}
function details(p,isProposal=false){const s=isProposal?null:C.projectStats(state.data,p.id);let content=`<div class="report-meta">${badge(p.status)}<span>ปีงบประมาณ ${p.fiscal_year}</span><span>${E(unit(p.unit_id))}</span></div><h3 style="font-size:18px;color:#4c6b96">${E(p.title)}</h3><div class="grid-2">${[['ผู้รับผิดชอบ',p.owner_name],['วงเงิน'+(isProposal?'ที่ขอ':'อนุมัติ'),C.money(isProposal?p.requested_budget:p.approved_budget)+' บาท'],['เริ่ม / สิ้นสุด',date(p.start_date)+' – '+date(p.end_date)],['กำหนดส่งรายงาน',date(p.report_due)],['วัตถุประสงค์',p.objectives],['รายละเอียด',p.description],['ผลพิจารณา',p.review_note||'—']].map(([k,v])=>`<div><div class="detail-label">${k}</div><div class="detail-value">${E(v)}</div></div>`).join('')}</div>`;if(s)content+=`<div class="metrics-3" style="margin-top:22px">${[['จัดสรรแล้ว',s.allocated],['จ่ายจริง',s.paid],['ใช้ได้อีก (หักรออนุมัติ)',s.available]].map(([k,v])=>`<div class="card"><small>${k}</small><strong style="font-size:20px">${C.money(v)}</strong></div>`).join('')}</div>`;if(isProposal&&p.status==='pending'&&can('proposals','approve')){if(p.owner_id===state.me.user_id)content+='<p class="info amber" style="margin-top:20px">ให้ผู้บริหารหรือ Admin อีกคนพิจารณา เพื่อแยกผู้เสนอและผู้อนุมัติ</p>';else content+=form('proposal-review',select('ผลการพิจารณา','decision','<option value="approved">อนุมัติและสร้างโครงการ</option><option value="returned">ส่งกลับแก้ไข</option><option value="rejected">ไม่อนุมัติ</option>')+moneyInput('วงเงินอนุมัติ (บาท)','approved_budget',p.requested_budget)+area('ความเห็น / เหตุผล (จำเป็นเมื่อส่งกลับหรือไม่อนุมัติ)','note'),'บันทึกผลพิจารณา',{id:p.id,version:p.version});}else if(!isProposal&&can('reports'))content+=`<div class="form-buttons">${btn('จัดทำ / ดูรายงาน','report-open',p.id,'primary')}</div>`;modal(isProposal?'รายละเอียดข้อเสนอโครงการ':'รายละเอียดโครงการ',content,true);}
function claimDetails(w){let content=`<div class="report-meta">${badge(w.status)}<span>${E(unit(w.unit_id))}</span><span>${C.money(w.amount)} บาท</span></div><h3 style="font-size:17px;color:#4c6b96">${E(w.purpose)}</h3><div class="detail-label">โครงการ / แหล่งงบประมาณ</div><div class="detail-value">${E(project(w.project_id)?.title||'งบส่วนกลาง')}<br>${E(source(w.fund_id)?.name)}</div><div class="detail-label">ผู้ขอ</div><div class="detail-value">${E(w.requester_name)} · ${date(w.created_at)}</div><div class="detail-label">ความเห็นผู้พิจารณา</div><div class="detail-value">${E(w.reviewer_name||'—')} · ${E(w.review_note||'—')}</div>`;if(w.status==='pending'&&can('disbursements','approve')){content+=w.requester_id===state.me.user_id?'<div class="info amber" style="margin-top:20px">ให้ผู้บริหารหรือ Admin อีกคนพิจารณาคำขอของคุณ</div>':form('claim-review',select('ผลพิจารณา','decision','<option value="approved">อนุมัติเบิกจ่าย</option><option value="rejected">ไม่อนุมัติ</option>')+area('ความเห็น / เหตุผล','note'),'บันทึกผลพิจารณา',{id:w.id,version:w.version});}if(w.status==='approved'&&can('payments','write'))content+=form('pay',input('เลขที่หลักฐาน / ใบสำคัญ','voucher_no','','text','required minlength="2"')+input('วันที่จ่ายจริง','payment_date',C.today(),'date',`required max="${C.today()}"`),'ยืนยันบันทึกจ่ายจริง',{id:w.id,version:w.version});if(w.status==='paid')content+=`<div class="info green" style="margin-top:20px">หลักฐานการจ่าย ${E(w.voucher_no)} · วันที่ ${date(w.payment_date)}</div>`;modal('รายละเอียดคำขอเบิกจ่าย',content);}
function claimForm(utility=false){modal(utility?'คำขอใช้จ่ายงบส่วนกลาง':'สร้างคำขอเบิกจ่าย',form(utility?'utility':'claim',(utility?fundSelect()+select('ประเภทค่าใช้จ่าย','kind','<option value="electricity">ค่าไฟฟ้า</option><option value="water">ค่าน้ำประปา</option><option value="internet">อินเทอร์เน็ต / โทรศัพท์</option><option value="utility">รายจ่ายส่วนกลางอื่น</option>'):projectSelect()+select('เบิกจากแหล่งเงิน','fund_id','<option value="">เลือกโครงการก่อน</option>','required',true))+input('รายการ / วัตถุประสงค์','purpose','','text','required minlength="3"',true)+moneyInput('จำนวนเงิน (บาท)','amount')+'<p class="full info" id="claim-balance">คำขอจะกันวงเงินทันทีเมื่อส่งพิจารณา</p>','ส่งคำขอเบิกจ่าย'));}
function updateClaimFunds(){const p=$('#action-form [name=project_id]')?.value;if(!p)return;const funds=[...new Set(state.data.allocations.filter(x=>x.project_id===p).map(x=>x.source_id))];$('#action-form [name=fund_id]').innerHTML=options(funds.map(id=>({id,name:source(id)?.name})),'id','name',funds[0]);updateClaimBalance();}
function updateClaimBalance(){const f=$('#action-form'),p=f?.elements.project_id?.value,id=f?.elements.fund_id?.value;if(!p||!id)return;const cap=C.sum(state.data.allocations.filter(x=>x.project_id===p&&x.source_id===id)),used=C.sum(state.data.disbursements.filter(x=>x.project_id===p&&x.fund_id===id&&['pending','approved','paid'].includes(x.status)));$('#claim-balance').textContent='ยอดใช้ได้จากแหล่งเงินนี้ '+C.money(cap-used)+' บาท (หักคำขอรอพิจารณาแล้ว)';}
function uploadForm(doc=false,replace){modal(doc?'แนบเอกสารโครงการ':'เพิ่มแบบฟอร์ม',form(doc?'document-upload':'form-upload',(doc?projectSelect(replace?.project_id):'')+input('ชื่อเอกสาร / แบบฟอร์ม','title',replace?replace.title+' (ฉบับแก้ไข)':'','text','required',true)+select('ประเภท','kind','<option value="permission">ขออนุญาต</option><option value="finance">การเงิน / เบิกจ่าย</option><option value="evidence">หลักฐานการดำเนินงาน</option><option value="other">อื่น ๆ</option>')+input('ไฟล์ (ไม่เกิน 10 MB)','file','','file','required accept=".pdf,.doc,.docx,.xlsx,.jpg,.jpeg,.png,.webp"',true)+area('คำอธิบาย','description'),'อัปโหลดและบันทึก'));}
async function blobData(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(blob);});}
const mimeMap={pdf:'application/pdf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp'};
async function upload(file,projectId){if(!file?.size||file.size>10485760)throw Error('ไฟล์ต้องมีขนาดไม่เกิน 10 MB');const ext=file.name.split('.').pop().toLowerCase(),mime=mimeMap[ext];if(!mime)throw Error('รองรับ PDF, Word, Excel และภาพ JPG / PNG / WebP');const path=(projectId?'projects/'+projectId+'/'+state.me.user_id:'forms/'+state.me.user_id)+'/'+C.uuid()+'.'+ext;if(state.demo){if(file.size>1500000)throw Error('โหมดสาธิตรองรับไฟล์ไม่เกิน 1.5 MB ต่อไฟล์');return {path,file_name:file.name,mime_type:mime,size_bytes:file.size,demo_data:await blobData(file)};}const {error}=await client.storage.from('andaman-pm-files').upload(path,file,{contentType:mime,upsert:false});if(error)throw error;return {path,file_name:file.name,mime_type:mime,size_bytes:file.size};}
async function downloadFile(key){const [kind,id]=key.split(':'),f=state.data[kind==='form'?'forms':'documents'].find(x=>x.id===id);if(!f)throw Error('ไม่พบไฟล์');let url;if(state.demo){if(!f.demo_data)throw Error('ไม่มีไฟล์แนบในข้อมูลตัวอย่างนี้');url=f.demo_data;}else{const {data,error}=await client.storage.from('andaman-pm-files').createSignedUrl(f.path,120,{download:f.file_name});if(error)throw error;url=data.signedUrl;}const a=document.createElement('a');a.href=url;a.download=f.file_name;a.rel='noopener';a.click();}
function memberForm(m){const isNew=!m;modal(isNew?'เพิ่มสมาชิก':'จัดการสมาชิก',form(isNew?'member-new':'member-edit',(isNew?select('รูปแบบบัญชี','mode','<option value="add_existing">เพิ่มบัญชี Supabase ที่มีอยู่แล้ว</option><option value="create">สร้างบัญชีใหม่</option>')+input('อีเมล','email','','email','required')+input('รหัสผ่านเริ่มต้น (สำหรับบัญชีใหม่)','password','','password','minlength="12" autocomplete="new-password"')+'<p class="full info">บัญชีเดิมใช้รหัสผ่านเดิม ระบบไม่เปลี่ยนรหัสผ่านหรือส่งอีเมลอัตโนมัติ บัญชีใหม่ให้ Admin แจ้งรหัสเริ่มต้นแก่เจ้าของบัญชีโดยตรง</p>':'')+input('ชื่อ – นามสกุล','display_name',m?.display_name,'text','required',true)+select('บทบาท','role',Object.entries(C.roleNames).map(([k,v])=>`<option value="${k}" ${m?.role===k?'selected':''}>${v}</option>`).join(''))+select('หน่วยงาน','unit_id',options(state.data.units.filter(x=>x.active),'id','name',m?.unit_id),'required',true)+(isNew?'':select('สถานะบัญชี','active',`<option value="true" ${m.active?'selected':''}>ใช้งาน</option><option value="false" ${!m.active?'selected':''}>ระงับการเข้าใช้ระบบโครงการ</option>`)),'บันทึกสมาชิก',{id:m?.user_id}));}
function unitForm(u={}){modal(u.id?'แก้ไขหน่วยงาน':'เพิ่มกลุ่มงาน',form('unit',input('ชื่อหน่วยงาน / กลุ่มงาน','name',u.name,'text','required minlength="2"',true)+select('หน่วยงานแม่','parent_id',options(state.data.units.filter(x=>x.id!==u.id),'id','name',u.parent_id,'ส่วนงานระดับสถาบัน / ไม่มีหน่วยงานแม่'),' ',true)+select('ประเภท','kind',Object.entries({work:'กลุ่มงานตามคำสั่ง',office:'สำนักงาน / หน่วยงาน',bureau:'สำนัก',center:'ศูนย์',college:'สถานศึกษา'}).map(([k,v])=>`<option value="${k}" ${u.kind===k?'selected':''}>${v}</option>`).join('')),'บันทึกโครงสร้าง',{unit_id:u.id}));}
async function openReport(id){await flushReportWorkspace();state.reportsView='tracking';$('#modal').close();const p=project(id);if(!p)throw Error('ไม่พบโครงการ');const r=state.data.reports.find(x=>x.project_id===id),s=C.projectStats(state.data,id);let payload={...(r?.payload||{}),projectName:p.title,academicYear:String(p.fiscal_year),schoolName:unit(p.unit_id),respName:p.owner_name,respDept:unit(p.unit_id),budgetPlanned:String(s.allocated),memoBudget:String(s.paid)};if(!payload.objectives)payload.objectives=(p.objectives||'').split('\n').filter(Boolean);if(!payload.q1Align)payload.q1Align=p.description||'';if(p.start_date&&!payload.startDate)payload.startDate=p.start_date;if(p.end_date&&!payload.endDate)payload.endDate=p.end_date;if(payload.photos?.length){payload.photos=await Promise.all(payload.photos.map(async a=>{if(a.base64)return a;if(state.demo)return a;const {data,error}=await client.storage.from('andaman-pm-files').download(a.path);if(error)throw error;return {...a,base64:await blobData(data)};}));}state.reportContext={id,memberId:state.me.user_id,version:r?.version||0,payload,readonly:!can('reports','write')||['submitted','accepted'].includes(r?.status),demo:state.demo};$('#main').innerHTML=header('จัดทำรายงานผลโครงการ',p.title,btn('กลับรายการ','go-reports'))+`<div class="report-meta"><span>${E(p.code)}</span><span>งบจัดสรร ${C.money(s.allocated)} บาท</span><span>จ่ายจริง ${C.money(s.paid)} บาท</span>${badge(r?.status||'draft')}</div><iframe id="report-frame" class="report-iframe" title="จัดทำรายงานโครงการ" src="report-editor/index.html?embedded=1"></iframe>`;}
window.addEventListener('message',async e=>{const frame=$('#report-frame');if(e.origin!==location.origin||e.source!==frame?.contentWindow)return;const c=state.reportContext;if(!c)return;if(e.data?.type==='pm-report-ready')frame.contentWindow.postMessage({type:'pm-report-init',...c},location.origin);if(e.data?.type==='pm-report-save'){let uploaded=[];try{if(c.readonly)throw Error('รายงานนี้เปิดสำหรับตรวจอ่าน');const payload=structuredClone(e.data.payload);payload.photos=await Promise.all((payload.photos||[]).map(async a=>{if(a.path?.startsWith('projects/'+c.id+'/'))return {id:a.id,path:a.path,caption:a.caption,...(state.demo?{base64:a.base64}:{})};const blob=await(await fetch(a.base64)).blob(),f=new File([blob],a.id+(blob.type==='image/png'?'.png':blob.type==='image/webp'?'.webp':'.jpg'),{type:blob.type});const m=await upload(f,c.id);uploaded.push(m.path);return {id:a.id,path:m.path,caption:a.caption,...(state.demo?{base64:a.base64}:{})};}));await mutate(e.data.submit?'reports.submit':'reports.save',{project_id:c.id,version:c.version,payload},e.data.command_id);const r=state.data.reports.find(x=>x.project_id===c.id);c.version=r.version;c.readonly=['submitted','accepted'].includes(r.status);c.payload=r.payload;frame.contentWindow.postMessage({type:'pm-report-saved',version:r.version,readonly:c.readonly,photos:r.payload.photos||[],status:r.status},location.origin);toast(e.data.submit?'ส่งรายงานให้ผู้บริหารตรวจรับแล้ว':'บันทึกรายงานเข้าสู่โครงการแล้ว');}catch(err){if(uploaded.length&&!state.demo)await client.storage.from('andaman-pm-files').remove(uploaded);frame.contentWindow.postMessage({type:'pm-report-error',message:err.message},location.origin);toast(err.message,true);}}});
function reviewReport(id){const r=state.data.reports.find(x=>x.id===id);modal('ตรวจรับรายงานผล',`<p class="info">${E(project(r.project_id)?.title)} · เมื่อตรวจรับ โครงการจะเปลี่ยนเป็นเสร็จสิ้น</p>`+form('report-review',select('ผลตรวจรับ','decision','<option value="accepted">ตรวจรับรายงาน</option><option value="returned">ส่งกลับแก้ไข</option>')+area('ความเห็น / สิ่งที่ต้องแก้ไข','note'),'บันทึกผลตรวจรับ',{id:r.id,version:r.version}));}
function exportCSV(){let headers,list;if(state.page==='audit'){headers=['เวลา','ผู้ดำเนินการ','รายการ','อ้างอิง','เหตุผล'];list=rows('audit').map(a=>[a.created_at,a.actor_name,a.action,a.entity_id,a.detail?.note]);}else{headers=['รหัสโครงการ','ชื่อโครงการ','หน่วยงาน','ปีงบประมาณ','วงเงินอนุมัติ','งบจัดสรร','จ่ายจริง','รออนุมัติ','อนุมัติรอจ่าย','วงเงินใช้ได้','ความก้าวหน้า','กำหนดส่งรายงาน','สถานะโครงการ','สถานะรายงาน'];list=rows('projects').map(p=>{const s=C.projectStats(state.data,p.id),r=state.data.reports.find(x=>x.project_id===p.id);return [p.code,p.title,unit(p.unit_id),p.fiscal_year,p.approved_budget,s.allocated,s.paid,s.pending,s.approved,s.available,p.progress,p.report_due,C.statuses[p.status],C.statuses[r?.status||'draft']];});}const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const blob=new Blob(['\ufeff'+[headers,...list].map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Andaman-'+state.page+'-'+state.fy+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');if(nav){e.preventDefault();navigate(nav.dataset.page);return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){case'close-modal':$('#modal').close();break;case'demo-picker':modal('เลือกบทบาทเพื่อทดลองใช้งาน',`<p class="info amber">ข้อมูลสมมติสำหรับเรียนรู้ขั้นตอนงาน เก็บแยกจากฐานข้อมูลจริง</p><div class="demo-choices">${Object.entries(C.roleNames).map(([k,v])=>`<button class="demo-choice" data-action="demo-enter" data-id="${k}">${icon(k==='admin'?'shield':k==='executive'?'chart':'users')}<div><b>${v}</b><small>${k==='admin'?'จัดสรรงบ สมาชิก และสิทธิ์เมนู':k==='executive'?'ดูภาพรวมและพิจารณาอนุมัติ':'เสนอโครงการ ขอเบิกจ่าย และจัดทำรายงาน'}</small></div></button>`).join('')}</div>`);break;case'demo-enter':await enterDemo(id);break;case'logout':await flushReportWorkspace();if(!state.demo&&client)await client.auth.signOut();state.demo=false;state.raw=null;state.data=null;state.reportContext=null;authEpoch++;login();break;case'reset-demo':modal('เริ่มข้อมูลตัวอย่างใหม่','<p class="info amber">การเปลี่ยนแปลงในโหมดสาธิตจะถูกแทนที่ด้วยข้อมูลตัวอย่างเริ่มต้น</p><div class="form-buttons">'+btn('ยกเลิก','close-modal')+btn('เริ่มใหม่','reset-demo-confirm','','primary')+'</div>');break;case'reset-demo-confirm':state.raw=C.demoData();await local('put',state.raw);state.me=state.raw.members.find(x=>x.role===state.me.role);$('#modal').close();await refresh();break;case'filter':state.filter=id;render();break;case'proposal-new':proposalForm();break;case'proposal-edit':proposalForm(state.data.proposals.find(x=>x.id===id));break;case'proposal-detail':details(state.data.proposals.find(x=>x.id===id),true);break;case'project-detail':details(project(id));break;case'progress':{const p=project(id);modal('อัปเดตความก้าวหน้า',form('progress',input('ความก้าวหน้า (%)','progress',p.progress,'number','required min="0" max="100" step="1"'),'บันทึกความก้าวหน้า',{id:p.id,version:p.version}));break;}case'source-new':modal('เพิ่มแหล่งงบประมาณ',form('source',input('ชื่อแหล่งงบประมาณ','name','','text','required',true)+yearInput()+moneyInput('วงเงินตั้งต้น (บาท)','amount')+select('หมวดงบ','category','<option value="operating">งบดำเนินงาน</option><option value="investment">งบลงทุน</option><option value="subsidy">เงินอุดหนุน</option><option value="income">เงินรายได้</option><option value="reserve">งบสำรอง / อื่น ๆ</option>')+area('หมายเหตุ / อ้างอิง','note')));break;case'source-adjust':{const s=source(id);modal('ปรับวงเงินแหล่งงบประมาณ',form('source-adjust',moneyInput('วงเงินใหม่ (บาท)','amount',s.amount)+area('เหตุผลการปรับวงเงิน','note','',true),'บันทึกวงเงินใหม่',{id}));break;}case'allocation-new':modal('บันทึกจัดสรรงบโครงการ',form('allocation',projectSelect()+fundSelect()+moneyInput('จำนวนเงินจัดสรร (บาท)','amount')+area('หมายเหตุ / อ้างอิงคำสั่ง','note')));break;case'claim-new':claimForm();break;case'utility-new':claimForm(true);break;case'claim-detail':claimDetails(state.data.disbursements.find(x=>x.id===id));break;case'notifications':{const alerts=C.pending(state.data,state.me,state.fy);modal('การแจ้งเตือน',alerts.length?alerts.map(x=>`<div class="pending-row"><div class="pending-icon">${icon('bell')}</div><div><h3>${E(x.title)}</h3><p>${E(x.detail)}</p></div>${btn('เปิดรายการ','notification-go',x.menu,'small')}</div>`).join(''):empty('ไม่มีรายการรอดำเนินการ'));break;}case'notification-go':$('#modal').close();navigate(id);break;case'go-projects':navigate('projects');break;case'go-reports':navigate('reports');break;case'report-open':await openReport(id);break;case'report-review':reviewReport(id);break;case'reports-view':if(!['v2','tracking'].includes(id))return;state.reportsView=id;updateReportWorkspace();break;case'legacy-reports':state.reportsView='v2';state.reportContext=null;render();break;case'form-upload':uploadForm();break;case'document-upload':uploadForm(true);break;case'document-replace':uploadForm(true,state.data.documents.find(x=>x.id===id));break;case'file-download':await downloadFile(id);break;case'form-archive':modal('เก็บแบบฟอร์มเข้าคลัง',form('form-archive','<p class="full info">แบบฟอร์มนี้จะไม่แสดงในรายการดาวน์โหลดของสมาชิก โดยยังคงประวัติไว้</p>','ยืนยันเก็บเข้าคลัง',{id}));break;case'document-review':modal('ตรวจเอกสารขออนุญาต',form('document-review',select('ผลตรวจ','decision','<option value="accepted">ตรวจรับเอกสาร</option><option value="returned">ส่งกลับแก้ไข</option>')+area('ความเห็น','note'),'บันทึกผลตรวจ',{id}));break;case'member-new':memberForm();break;case'member-edit':memberForm(state.data.members.find(x=>x.user_id===id));break;case'unit-new':unitForm();break;case'unit-edit':unitForm(state.data.units.find(x=>x.id===id));break;case'export-csv':exportCSV();break;}}
catch(err){toast(err.message||'ดำเนินการไม่สำเร็จ',true);}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='login-form'){e.preventDefault();const button=f.querySelector('button');button.disabled=true;f.querySelector('.login-error').textContent='กำลังเข้าสู่ระบบ…';try{if(!client)throw Error('โหลดระบบยืนยันตัวตนไม่สำเร็จ');let email=f.elements.email.value.trim();email=cfg.loginAliases?.[email.toLowerCase()]||email;const {error}=await client.auth.signInWithPassword({email,password:f.elements.password.value});if(error)throw Error('เข้าสู่ระบบไม่สำเร็จ กรุณาตรวจสอบชื่อผู้ใช้และรหัสผ่าน');state.demo=false;state.page='dashboard';await refresh();}catch(err){login(err.message);}finally{button.disabled=false;}return;}if(f.id==='permissions-form'){e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{const role=state.permissionRole||'executive';for(const [menu] of C.menus){if(['members','permissions'].includes(menu))continue;const data={role,menu};for(const op of ['read','write','approve'])data['can_'+op]=!!f.elements[menu+':'+op]?.checked;await mutate('permissions.save',data,C.uuid());}toast('บันทึกสิทธิ์เมนูแล้ว');shell();}catch(err){toast(err.message,true);}finally{b.disabled=false;}return;}if(f.id!=='action-form')return;e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;const v=Object.fromEntries(new FormData(f)),ctx=state.modalContext||{},args={...v};if(ctx.id)args.id=ctx.id;if(ctx.version!==undefined)args.version=ctx.version;let action;try{switch(ctx.kind){case'proposal':action=v.submit_mode==='submit'?'proposals.submit':'proposals.save';break;case'proposal-review':action='proposals.review';break;case'source':action='sources.create';break;case'source-adjust':action='sources.adjust';break;case'allocation':action='allocations.create';break;case'claim':action='disbursements.create';break;case'utility':action='utilities.create';break;case'claim-review':action='disbursements.review';break;case'pay':action='disbursements.pay';break;case'progress':action='projects.progress';break;case'report-review':action='reports.review';break;case'document-review':action='documents.review';break;case'form-archive':action='forms.archive';break;case'unit':action='units.save';if(ctx.unit_id)args.unit_id=ctx.unit_id;break;case'member-edit':action='members.update';args.active=v.active==='true';break;case'member-new':{if(state.demo){await mutate('members.create',args,ctx.command_id);}else{if(v.mode==='create'&&v.password.length<12)throw Error('รหัสผ่านเริ่มต้นอย่างน้อย 12 ตัวอักษร');const {data,error}=await client.functions.invoke(cfg.membersFunction||'pm-members',{body:{action:v.mode,email:v.email,display_name:v.display_name,role:v.role,unit_id:v.unit_id,...(v.mode==='create'?{password:v.password}:{})}});if(error){let msg='เพิ่มสมาชิกไม่สำเร็จ';try{const body=await error.context.json();msg=body.message||body.error||msg;}catch{}throw Error(msg);}if(!data?.success)throw Error(data?.message||'เพิ่มสมาชิกไม่สำเร็จ');await refresh(false);}$('#modal').close();shell();toast('เพิ่มสมาชิกแล้ว');return;}case'form-upload':case'document-upload':{const doc=ctx.kind==='document-upload',meta=await upload(v.file,doc?v.project_id:null);delete args.file;Object.assign(args,meta);try{await mutate(doc?'documents.create':'forms.create',args,ctx.command_id);}catch(err){if(!state.demo)await client.storage.from('andaman-pm-files').remove([meta.path]);throw err;}$('#modal').close();shell();toast('จัดเก็บไฟล์แล้ว');return;}default:throw Error('ไม่พบคำสั่ง');}await mutate(action,args,ctx.command_id);$('#modal').close();shell();toast('บันทึกข้อมูลเรียบร้อยแล้ว');}catch(err){f.querySelector('.form-error').textContent=err.message;toast(err.message,true);}finally{b.disabled=false;}});
document.addEventListener('change',async e=>{const x=e.target;try{if(x.id==='fiscal-filter'){state.fy=+x.value;state.filter='all';shell();}if(x.id==='demo-role'){await flushReportWorkspace();const m=state.raw.members.find(m=>m.role===x.value&&m.active);if(!m)throw Error('ไม่มีสมาชิกตัวอย่างสำหรับบทบาทนี้');state.me=m;state.page='dashboard';await refresh();}if(x.id==='permission-role'){state.permissionRole=x.value;render();}if(x.closest('#action-form')&&state.modalContext?.kind==='claim'){if(x.name==='project_id')updateClaimFunds();if(x.name==='fund_id')updateClaimBalance();}}catch(err){toast(err.message,true);}});
document.addEventListener('keydown',e=>{if(!e.target.matches('.reports-tabs [role=tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();state.reportsView=e.key==='Home'?'v2':e.key==='End'?'tracking':state.reportsView==='v2'?'tracking':'v2';updateReportWorkspace();$('#reports-tab-'+state.reportsView).focus();});
$('#global-search').addEventListener('input',e=>{state.query=e.target.value;if(!state.reportContext)render();});$('#menu-toggle').addEventListener('click',()=>{const on=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(on));});document.addEventListener('click',e=>{if(innerWidth<=760&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle'))$('#sidebar').classList.remove('open');});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(state.me&&uiMenus.some(x=>x[0]===p)&&p!==state.page)navigate(p);});
if(client)client.auth.onAuthStateChange((event,session)=>{if(state.demo)return;if(event==='SIGNED_OUT'){state.me=null;state.data=null;authEpoch++;login();}if(event==='TOKEN_REFRESHED'&&session){setTimeout(()=>{if(state.me&&!state.demo)refresh(false).catch(err=>toast(err.message,true));},0);}});
paintIcons();login();if(client){try{const {data}=await client.auth.getSession();if(data.session){state.page=uiMenus.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard';await refresh();}}catch(err){login(err.message);}}
timer=setInterval(()=>{if(state.me&&!state.demo&&!document.hidden&&state.page!=='permissions'&&state.page!=='guide'&&!$('#modal').open&&!state.reportContext&&!$('#andaman-report-v2-frame'))refresh().catch(err=>toast('โหลดข้อมูลล่าสุดไม่สำเร็จ: '+err.message,true));},30000);
})();
